class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        n, m = len(grid), len(grid[0])
        result = []
        idx = 0  # position in traversal order
        for r in range(n):
            cols = range(m) if r % 2 == 0 else range(m - 1, -1, -1)
            for c in cols:
                if idx % 2 == 0:
                    result.append(grid[r][c])
                idx += 1
        return result
