from collections import deque
from typing import List, Tuple

class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        def is_sorted(a: Tuple[int]) -> bool:
            return all(a[i] >= a[i-1] for i in range(1, len(a)))

        start = tuple(nums)
        if is_sorted(start):
            return 0

        seen = {start}
        q = deque([(start, 0)])

        while q:
            arr, step = q.popleft()
            n = len(arr)
            # find min sum pair and leftmost if tie
            min_sum = None
            min_idx = None
            for i in range(n-1):
                s = arr[i] + arr[i+1]
                if min_sum is None or s < min_sum:
                    min_sum = s
                    min_idx = i
            # perform merge
            new_arr = arr[:min_idx] + (min_sum,) + arr[min_idx+2:]
            if is_sorted(new_arr):
                return step + 1
            if new_arr not in seen:
                seen.add(new_arr)
                q.append((new_arr, step+1))
        return -1  # should never reach here
