class Solution:
    def minCost(self, n: int, cost: list[list[int]]) -> int:
        m = n // 2
        INF = 10**18
        # dp[cL][cR] minimal cost for current pair
        dp = [[INF]*3 for _ in range(3)]
        # init first pair
        for cL in range(3):
            for cR in range(3):
                if cL == cR:
                    continue
                dp[cL][cR] = cost[0][cL] + cost[n-1][cR]
        # iterate remaining pairs
        for i in range(1, m):
            ndp = [[INF]*3 for _ in range(3)]
            for cL in range(3):
                for cR in range(3):
                    if dp[cL][cR] == INF:
                        continue
                    for dL in range(3):
                        if dL == cL: continue
                        for dR in range(3):
                            if dR == cR: continue
                            if dL == dR: continue
                            val = dp[cL][cR] + cost[i][dL] + cost[n-1-i][dR]
                            if val < ndp[dL][dR]:
                                ndp[dL][dR] = val
            dp = ndp
        ans = INF
        for cL in range(3):
            for cR in range(3):
                if dp[cL][cR] < ans:
                    ans = dp[cL][cR]
        return ans
