class LiChaoNode:
    __slots__ = ('l','r','line')
    def __init__(self,l,r):
        self.l=l; self.r=r; self.line=None

class LiChao:
    def __init__(self,l,r):
        self.root=LiChaoNode(l,r)
    def add_line(self,m,b):
        self._add(self.root,m,b)
    def _add(self,node,m,b):
        l,r=node.l,node.r
        mid=(l+r)//2
        cur=node.line
        if cur is None:
            node.line=(m,b)
            return
        def val(x):
            return cur[0]*x+cur[1]
        def val_new(x):
            return m*x+b
        if val_new(mid)<val(mid):
            node.line=(m,b)
            cur=node.line
        if l==r:
            return
        if val_new(l)<val(l):
            if node.l is None:
                node.l=LiChaoNode(l,mid)
            self._add(node.l,m,b)
        elif val_new(r)<val(r):
            if node.r is None:
                node.r=LiChaoNode(mid+1,r)
            self._add(node.r,m,b)
    def query(self,x):
        return self._query(self.root,x)
    def _query(self,node,x):
        if node is None:
            return 10**18
        l,r=node.l,node.r
        res=node.line[0]*x+node.line[1] if node.line else 10**18
        if l==r:
            return res
        mid=(l+r)//2
        if x<=mid:
            return min(res,self._query(node.l,x))
        else:
            return min(res,self._query(node.r,x))

