class Solution:
    def maxSum(self, nums, k, m):
        n = len(nums)
        prefix = [0]*(n+1)
        for i in range(1,n+1):
            prefix[i] = prefix[i-1]+nums[i-1]
        best_end = [-10**18]*(n+1)
        for i in range(1,n+1):
            if i>=m:
                best_end[i] = max(best_end[i-1]+nums[i-1], prefix[i]-prefix[i-m])
            else:
                best_end[i] = -10**18
        dp = [[-10**18]*(k+1) for _ in range(n+1)]
        dp[0][0] = 0
        for i in range(1,n+1):
            dp[i][0] = 0
            for t in range(1,k+1):
                dp[i][t] = dp[i-1][t]
                if i>=m:
                    val = dp[i-m][t-1] + best_end[i]
                    if val>dp[i][t]:
                        dp[i][t] = val
        return dp[n][k]
