                parent[x] = find(parent[x])
            return parent[x]

        unplaced = 0
        for f in fruits:
            idx = find(0)
            while idx < n and baskets[idx] < f:
                parent[idx] = find(idx + 1)  # skip this basket
                idx = find(idx)
