import sys
sys.setrecursionlimit(1 << 25)

def solve() -> None:
    input = sys.stdin.readline
    N = int(input().strip())
    S = input().strip()
    T = input().strip()

    # mapping from letter to set of target letters
    from collections import defaultdict
    target = defaultdict(set)
    for s, t in zip(S, T):
        if s != t:
            target[s].add(t)

    # check impossible: same source maps to >1 target
    for src, tgtset in target.items():
        if len(tgtset) > 1:
            print(-1)
            return

    # build directed graph of changes
    graph = defaultdict(list)
    for src, tgtset in target.items():
        for dst in tgtset:
            graph[src].append(dst)

    # count letters that need change
    need_change = len(target)

    # Tarjan SCC to detect cycles
    index = {}
    lowlink = {}
    stack = []
    onstack = set()
    idx = 0
    cycle_scc = 0

    def strongconnect(v):
        nonlocal idx, cycle_scc
        index[v] = lowlink[v] = idx
        idx += 1
        stack.append(v)
        onstack.add(v)
        for w in graph.get(v, []):
            if w not in index:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif w in onstack:
                lowlink[v] = min(lowlink[v], index[w])
        if lowlink[v] == index[v]:
            comp = []
            while True:
                w = stack.pop()
                onstack.remove(w)
                comp.append(w)
                if w == v:
                    break
            if len(comp) > 1:
                cycle_scc += 1
            elif v in graph and v in graph[v]:  # self-loop
                cycle_scc += 1

    for v in target.keys():
        if v not in index:
            strongconnect(v)

    print(need_change + cycle_scc)

if __name__ == "__main__":
    solve()
```

