class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n
        # build trie with counts
        trie = [{}]
        count = [0]
        for w in words:
            node = 0
            for ch in w:
                if ch not in trie[node]:
                    trie[node][ch] = len(trie)
                    trie.append({})
                    count.append(0)
                node = trie[node][ch]
                count[node] += 1
        res = []
        for w in words:
            node = 0
            best = 0
            for i, ch in enumerate(w, 1):
                node = trie[node][ch]
                if count[node] > k:
                    best = i
                else:
                    break
            res.append(best)
        return res
