class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_val = max(max(groups, default=0), max(elements, default=0))
        min_index = [-1] * (max_val + 1)
        for idx, val in enumerate(elements):
            if min_index[val] == -1 or idx < min_index[val]:
                min_index[val] = idx
        res = []
        for g in groups:
            best = -1
            d = 1
            while d * d <= g:
                if g % d == 0:
                    idx1 = min_index[d]
                    if idx1 != -1:
                        if best == -1 or idx1 < best:
                            best = idx1
                    other = g // d
                    if other != d:
                        idx2 = min_index[other]
                        if idx2 != -1:
                            if best == -1 or idx2 < best:
                                best = idx2
                d += 1
            res.append(best)
        return res
