class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        from collections import defaultdict
        import heapq

        # Sort events by timestamp; OFFLINE events processed before MESSAGE at same time
        sorted_events = sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        offline = set()
        reonline_heap = []  # (time, id)
        mentions = [0] * numberOfUsers

        for ev in sorted_events:
            t = int(ev[1])
            # Process re-online events up to current time
            while reonline_heap and reonline_heap[0][0] <= t:
                _, uid = heapq.heappop(reonline_heap)
                offline.discard(uid)

            if ev[0] == "OFFLINE":
                uid = int(ev[2])
                offline.add(uid)
                heapq.heappush(reonline_heap, (t + 60, uid))
            else:  # MESSAGE
                msg = ev[2]
                if msg == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif msg == "HERE":
                    for i in range(numberOfUsers):
                        if i not in offline:
                            mentions[i] += 1
                else:
                    tokens = msg.split()
                    for token in tokens:
                        if token.startswith("id"):
                            uid = int(token[2:])
                            mentions[uid] += 1
        return mentions
