def solve():
    N = int(sys.stdin.readline().strip())
    limit = int(round(N ** (1/3))) + 2
    for d in range(1, limit + 1):
        if d * d * d > N + d**3:
            break
        if N % d != 0 and N % (d * d * d) != 0:
            continue
        # compute discriminant
        D = 21 * d**4 - 12 * d * N
        if D < 0:
            continue
        s = int(math.isqrt(D))
        if s * s != D:
            continue
        # solve for y: y = (-3d^2 + s) / (6d)
        num = -3 * d * d + s
        den = 6 * d
        if num <= 0 or num % den != 0:
            continue
        y = num // den
        if y <= 0:
            continue
        x = y + d
        if x**3 - y**3 == N:
            print(f"{x} {y}")
            return
    print(-1)

if __name__ == "__main__":
    solve()
