        n = len(s)
        for i in range(n - k + 1):
            sub = s[i:i + k]
            if len(set(sub)) != 1:
                continue
            c = sub[0]
            if i > 0 and s[i - 1] == c:
                continue
            if i + k < n and s[i + k] == c:
                continue
            return True
        return False
