    H = int(next(it)); W = int(next(it))
    A = [[int(next(it)) for _ in range(W)] for _ in range(H)]
    Q = int(next(it)); sh = int(next(it))-1; sw = int(next(it))-1

    # precompute dp once
    dp = [[0]*W for _ in range(H)]
    dp[0][0] = A[0][0] % MOD
    for j in range(1, W):
        dp[0][j] = dp[0][j-1] * A[0][j] % MOD
    for i in range(1, H):
        dp[i][0] = dp[i-1][0] * A[i][0] % MOD
    for i in range(1, H):
        for j in range(1, W):
            dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD
            dp[i][j] = dp[i][j] * A[i][j] % MOD

    out_lines = []
    cur_h, cur_w = sh, sw
    for _ in range(Q):
        d = next(it)
        a = int(next(it))
        if d == 'L':
            cur_w -= 1
        elif d == 'R':
            cur_w += 1
        elif d == 'U':
            cur_h -= 1
        else:
            cur_h += 1
        A[cur_h][cur_w] = a % MOD

        # recompute dp from start to end
        dp[0][0] = A[0][0] % MOD
        for j in range(1, W):
            dp[0][j] = dp[0][j-1] * A[0][j] % MOD
        for i in range(1, H):
            dp[i][0] = dp[i-1][0] * A[i][0] % MOD
        for i in range(1, H):
            for j in range(1, W):
                dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD
                dp[i][j] = dp[i][j] * A[i][j] % MOD

        out_lines.append(str(dp[H-1][W-1] % MOD))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
