class Solution:
    def maxSum(self, grid: list[list[int]], limits: list[int], k: int) -> int:
        n = len(grid)
        items = []
        for i in range(n):
            for val in grid[i]:
                items.append((val, i))
        items.sort(reverse=True, key=lambda x: x[0])
        taken = [0] * n
        total = 0
        count = 0
        for val, i in items:
            if count >= k:
                break
            if taken[i] < limits[i]:
                total += val
                taken[i] += 1
                count += 1
        return total
