class Solution:
    def maxSum(self, grid, limits, k):
        candidates = []
        for r, limit in enumerate(limits):
            if limit == 0:
                continue
            row_vals = sorted(grid[r], reverse=True)[:limit]
            candidates.extend(row_vals)
        if not candidates or k == 0:
            return 0
        candidates.sort(reverse=True)
        return sum(candidates[:k])
