        pizzas.sort(reverse=True)
        total = 0
        for day, i in enumerate(range(0, len(pizzas), 4)):
            if day % 2 == 0:          # odd day (1-indexed)
                total += pizzas[i + 3]
            else:                     # even day
                total += pizzas[i + 2]
        return total
